                        new_elements.add(generator)
            ball.update(new_elements)
            generators.update(new_elements)
        return len(generators)

    def anova_test(dimensions):
        n = len(dimensions)
        mean = sum(dimensions) / n
        variance = sum((x - mean) ** 2 for x in dimensions) / (n - 1)
        if variance == 0:
            return False, "Metric saturation"
        f_statistic = (mean / (variance / n)) * (n - 1)
        critical_value = 3.8415  # Chi-squared distribution with 1 degree of freedom at p=0.05
